b.lessons=[]
ROOT=b.ROOT
SOURCE=quote('استاد حاکمی.pdf')
def refs(pages):
    return '<span class="refs">صفحه در جزوهٔ اصلی: '+ '، '.join(f'<a href="../{SOURCE}#page={p}" target="_blank" rel="noopener">{p}</a>' for p in pages)+'</span>'
b.refs=refs
T=b.table; U=b.ul; S=b.steps; Q=b.q; E=b.en
def P(text): return '<p>'+text+'</p>'
def D(title,body): return '<details class="explanation"><summary>'+title+'</summary>'+body+'</details>'
def L(part,title,pages,overview,goals,body,memory,questions,check):
    b.lesson(part,title,pages,overview,goals,body,memory,[Q(*q,pages) for q in questions],check)

